// Local Analysis Engine - Process ImpactCO2 API Data
// This code should be placed in a "Code" node in n8n

// Get the input data from the previous node
const inputData = $input.all();

// Process each item from the HTTP Request
const processedItems = inputData.map(item => {
  const data = item.json.data;

  // If data is an array, process each element
  if (Array.isArray(data)) {
    return data.map(entry => ({
      // Original data
      id: entry.id,
      name: entry.name,
      value: entry.value,

      // Analysis metrics
      analysis: {
        carbonIntensity: entry.value,
        category: classifyTransport(entry.name),
        rating: getRating(entry.value),
        comparison: compareToAverage(entry.value),
        recommendation: getRecommendation(entry.value, entry.name)
      },

      // Metadata
      metadata: {
        processedAt: new Date().toISOString(),
        source: 'ImpactCO2 API',
        unit: 'kg CO2e per km'
      }
    }));
  }

  // If data is a single object
  return [{
    id: data.id,
    name: data.name,
    value: data.value,
    analysis: {
      carbonIntensity: data.value,
      category: classifyTransport(data.name),
      rating: getRating(data.value),
      comparison: compareToAverage(data.value),
      recommendation: getRecommendation(data.value, data.name)
    },
    metadata: {
      processedAt: new Date().toISOString(),
      source: 'ImpactCO2 API',
      unit: 'kg CO2e per km'
    }
  }];
});

// Helper Functions

function classifyTransport(name) {
  const lower = name.toLowerCase();
  if (lower.includes('bus') || lower.includes('autocar')) return 'Public Transport - Bus';
  if (lower.includes('train') || lower.includes('ter') || lower.includes('tgv')) return 'Public Transport - Rail';
  if (lower.includes('métro') || lower.includes('metro') || lower.includes('tramway')) return 'Public Transport - Urban';
  if (lower.includes('voiture') || lower.includes('car')) return 'Private Vehicle';
  if (lower.includes('vélo') || lower.includes('bike') || lower.includes('trottinette')) return 'Active Mobility';
  if (lower.includes('avion') || lower.includes('plane')) return 'Air Travel';
  return 'Other';
}

function getRating(value) {
  if (value < 0.1) return 'Excellent';
  if (value < 0.5) return 'Very Good';
  if (value < 1.0) return 'Good';
  if (value < 1.5) return 'Moderate';
  if (value < 2.0) return 'High';
  return 'Very High';
}

function compareToAverage(value) {
  // Average car emissions ~0.193 kg CO2e/km
  const carAverage = 0.193;
  const percentage = ((value / carAverage) * 100).toFixed(0);

  if (value < carAverage) {
    return `${percentage}% of average car emissions (better)`;
  } else {
    return `${percentage}% of average car emissions (worse)`;
  }
}

function getRecommendation(value, name) {
  if (value < 0.1) {
    return `${name} is an excellent low-carbon choice. Keep using this mode of transport!`;
  } else if (value < 1.0) {
    return `${name} is a good choice with moderate emissions. Consider this for longer distances.`;
  } else if (value < 2.0) {
    return `${name} has relatively high emissions. Consider alternatives like public transport or carpooling when possible.`;
  } else {
    return `${name} has very high carbon emissions. Try to limit use and explore lower-emission alternatives.`;
  }
}

// Flatten the array and return
return processedItems.flat().map(item => ({ json: item }));

const items = $input.all();

// Create a comprehensive context for the AI
const transportData = items.map(item => item.json);

// Sort by carbon intensity
transportData.sort((a, b) => a.value - b.value);

// Build structured summary
const summary = {
  totalOptions: transportData.length,
  bestOption: transportData[0],
  worstOption: transportData[transportData.length - 1],
  averageEmissions: (transportData.reduce((sum, t) => sum + t.value, 0) / transportData.length).toFixed(3),
  allTransportData: transportData
};

// Create AI-friendly context message
const contextMessage = `
I have analyzed ${summary.totalOptions} transportation options from the ImpactCO2 API.

🌱 BEST OPTION: ${summary.bestOption.name}
- Carbon Intensity: ${summary.bestOption.value} kg CO2e/km
- Rating: ${summary.bestOption.analysis.rating}
- ${summary.bestOption.analysis.comparison}

⚠️ HIGHEST EMISSIONS: ${summary.worstOption.name}
- Carbon Intensity: ${summary.worstOption.value} kg CO2e/km
- Rating: ${summary.worstOption.analysis.rating}

📊 AVERAGE EMISSIONS: ${summary.averageEmissions} kg CO2e/km

COMPLETE TRANSPORTATION DATA:
${transportData.map((t, i) => `
${i + 1}. ${t.name}
   - Emissions: ${t.value} kg CO2e/km
   - Category: ${t.analysis.category}
   - Rating: ${t.analysis.rating}
   - ${t.analysis.comparison}
   - Recommendation: ${t.analysis.recommendation}
`).join('')}

---
This data can help answer questions about:
- Which transport mode is most eco-friendly
- How different vehicles compare in carbon emissions
- Recommendations for reducing your carbon footprint
- Environmental impact of travel choices

How can I help you understand this transportation data?
`;

return [{
  json: {
    summary: summary,
    aiContext: contextMessage,
    transportData: transportData,
    timestamp: new Date().toISOString()
  }
}];

// Get the AI response from the previous node
const aiResponse = $input.first();

// Extract the AI's message based on which provider you're using
let message;

// If you're using OpenAI:
if (aiResponse.json.choices) {
  message = aiResponse.json.choices[0].message.content;
} 
// If you're using Claude (via HTTP Request):
else if (aiResponse.json.content) {
  message = aiResponse.json.content[0].text;
}
// Fallback if structure is different:
else {
  message = JSON.stringify(aiResponse.json);
}

// Format for chat display
const chatOutput = {
  type: 'ai_response',
  timestamp: new Date().toISOString(),
  message: message,
  transportDataAvailable: true,
  suggestedActions: [
    'Compare specific transport modes',
    'Get personalized recommendations',
    'Calculate trip emissions',
    'Find eco-friendly alternatives'
  ]
};

return [{ json: chatOutput }];

// ============================================
// NODE 1: Local Analysis Engine (French)
// ============================================

const inputData = $input.all();

// Distance du trajet (changez cette valeur selon vos besoins)
const httpRequestData = $('HTTP_Request').first();
const tripDistanceKm = httpRequestData?.json?.km || 
                       httpRequestData?.params?.km || 
                       10; // Valeur par défaut si non trouvée

const processedItems = inputData.map(item => {
  // Gérer différents formats de réponse API
  let data = item.json.data || item.json;

  if (!data && Array.isArray(item.json)) {
    data = item.json;
  }

  if (!Array.isArray(data)) {
    data = [data];
  }

  return data.map(entry => {
    const totalEmissions = entry.value;
    const emissionsPerKm = totalEmissions / tripDistanceKm;

    return {
      id: entry.id,
      name: entry.name,
      totalEmissions: totalEmissions,
      emissionsPerKm: emissionsPerKm,
      tripDistance: tripDistanceKm,

      analysis: {
        carbonIntensity: emissionsPerKm,
        totalCarbonFootprint: totalEmissions,
        category: classifyTransport(entry.name),
        rating: getRating(totalEmissions, tripDistanceKm),
        absoluteRating: getAbsoluteRating(totalEmissions, tripDistanceKm),
        comparison: compareToAverage(emissionsPerKm, totalEmissions, tripDistanceKm),
        impactEquivalent: getImpactEquivalent(totalEmissions),
        recommendation: getRecommendation(totalEmissions, entry.name, tripDistanceKm)
      },

      metadata: {
        processedAt: new Date().toISOString(),
        source: 'API ImpactCO2',
        unit: 'kg CO2e par km',
        totalUnit: 'kg CO2e total',
        distance: `${tripDistanceKm} km`
      }
    };
  });
});

// Fonctions d'aide
function classifyTransport(name) {
  const lower = name.toLowerCase();

  if (lower.includes('bus') || lower.includes('autocar') || lower.includes('autobus')) {
    return 'Transport Public - Bus';
  }

  if (lower.includes('train') || lower.includes('ter') || lower.includes('tgv') || 
      lower.includes('intercités') || lower.includes('transilien')) {
    return 'Transport Public - Train';
  }

  if (lower.includes('métro') || lower.includes('metro') || lower.includes('tramway') || 
      lower.includes('tram')) {
    return 'Transport Public - Urbain';
  }

  if (lower.includes('voiture') || lower.includes('automobile') || lower.includes('suv') ||
      lower.includes('citadine') || lower.includes('berline')) {
    return 'Véhicule Privé';
  }

  if (lower.includes('vélo') || lower.includes('velo') || lower.includes('marche') || 
      lower.includes('trottinette') || lower.includes('vae')) {
    return 'Mobilité Active';
  }

  if (lower.includes('avion') || lower.includes('vol')) {
    return 'Transport Aérien';
  }

  if (lower.includes('moto') || lower.includes('scooter')) {
    return 'Deux-roues Motorisé';
  }

  return 'Autre';
}

function getRating(totalEmissions, distance) {
  const emissionsPerKm = totalEmissions / distance;

  if (emissionsPerKm < 0.01) return 'Excellent ⭐⭐⭐⭐⭐';
  if (emissionsPerKm < 0.05) return 'Très Bon ⭐⭐⭐⭐';
  if (emissionsPerKm < 0.1) return 'Bon ⭐⭐⭐';
  if (emissionsPerKm < 0.2) return 'Moyen ⭐⭐';
  if (emissionsPerKm < 0.5) return 'Élevé ⭐';
  return 'Très Élevé ⚠️';
}

function getAbsoluteRating(totalEmissions, distance) {
  if (totalEmissions < 0.5) {
    return `Impact Minimal (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km)`;
  }
  if (totalEmissions < 2) {
    return `Impact Faible (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km)`;
  }
  if (totalEmissions < 5) {
    return `Impact Modéré (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km)`;
  }
  if (totalEmissions < 10) {
    return `Impact Élevé (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km)`;
  }
  if (totalEmissions < 50) {
    return `Impact Très Élevé (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km)`;
  }
  return `Impact Sévère (${totalEmissions.toFixed(2)} kg CO2e pour ${distance} km) ⚠️`;
}

function compareToAverage(emissionsPerKm, totalEmissions, tripDistance) {
  const carAverage = 0.193;
  const carTotalEmissions = carAverage * tripDistance;
  const percentage = ((emissionsPerKm / carAverage) * 100).toFixed(0);
  const difference = Math.abs(totalEmissions - carTotalEmissions).toFixed(2);

  if (emissionsPerKm < carAverage) {
    return `${percentage}% des émissions d'une voiture - ÉCONOMISE ${difference} kg CO2e sur ce trajet de ${tripDistance}km ! 🌱`;
  } else if (emissionsPerKm === carAverage) {
    return `Équivalent aux émissions d'une voiture moyenne (${carTotalEmissions.toFixed(2)} kg CO2e pour ${tripDistance}km)`;
  } else {
    return `${percentage}% des émissions d'une voiture - COÛTE ${difference} kg CO2e de plus qu'une voiture pour ${tripDistance}km ⚠️`;
  }
}

function getImpactEquivalent(totalEmissions) {
  const treesNeeded = (totalEmissions / 21).toFixed(1);
  const smartphoneCharges = (totalEmissions / 0.008).toFixed(0);
  const meatMeals = (totalEmissions / 2.5).toFixed(1);

  if (totalEmissions < 0.5) {
    return `Équivalent à ${smartphoneCharges} charges de smartphone`;
  } else if (totalEmissions < 5) {
    return `Équivalent à ${meatMeals} repas de bœuf ou ${treesNeeded} arbres nécessaires pendant un an pour compenser`;
  } else if (totalEmissions < 20) {
    return `Nécessiterait ${treesNeeded} arbres travaillant une année complète pour compenser ce trajet`;
  } else {
    return `Impact massif ! Il faudrait ${treesNeeded} arbres travaillant une année complète pour compenser. Envisagez des alternatives !`;
  }
}

function getRecommendation(totalEmissions, name, distance) {
  if (totalEmissions < 0.5) {
    return `${name} est un excellent choix pour votre trajet de ${distance}km ! Émissions totales de seulement ${totalEmissions.toFixed(2)} kg CO2e.`;
  } else if (totalEmissions < 2) {
    return `${name} est un bon choix pour ${distance}km avec ${totalEmissions.toFixed(2)} kg CO2e d'émissions totales.`;
  } else if (totalEmissions < 10) {
    return `${name} produit ${totalEmissions.toFixed(2)} kg CO2e pour ${distance}km - envisagez le covoiturage ou les transports en commun pour réduire l'impact.`;
  } else {
    return `${name} génère ${totalEmissions.toFixed(2)} kg CO2e pour ${distance}km - c'est assez élevé ! Privilégiez fortement des alternatives comme le train ou le bus.`;
  }
}

return processedItems.flat().map(item => ({ json: item }));

// ============================================
// NODE 2: Format Final Output (French)
// ============================================
// Préparer le contexte pour l'IA en français

const items = $input.all();

// Créer un contexte complet pour l'IA
const transportData = items.map(item => item.json);

// Trier par émissions TOTALES (pas par km)
transportData.sort((a, b) => a.totalEmissions - b.totalEmissions);

// Construire un résumé structuré
const tripDistance = transportData[0].tripDistance;
const summary = {
  tripDistance: tripDistance,
  totalOptions: transportData.length,
  bestOption: transportData[0],
  worstOption: transportData[transportData.length - 1],
  averageEmissionsPerKm: (transportData.reduce((sum, t) => sum + t.emissionsPerKm, 0) / transportData.length).toFixed(3),
  averageTotalEmissions: (transportData.reduce((sum, t) => sum + t.totalEmissions, 0) / transportData.length).toFixed(2),
  totalEmissionsSaved: (transportData[transportData.length - 1].totalEmissions - transportData[0].totalEmissions).toFixed(2),
  allTransportData: transportData
};

// Créer un message contextuel convivial pour l'IA
const contextMessage = `
J'ai analysé ${summary.totalOptions} options de transport pour un trajet de ${tripDistance} km en utilisant les données de l'API ImpactCO2.

🌱 MEILLEURE OPTION : ${summary.bestOption.name}
- Émissions totales : ${summary.bestOption.totalEmissions.toFixed(2)} kg CO2e pour ${tripDistance} km
- Par km : ${summary.bestOption.emissionsPerKm.toFixed(4)} kg CO2e/km
- Note : ${summary.bestOption.analysis.rating}
- Impact : ${summary.bestOption.analysis.absoluteRating}
- ${summary.bestOption.analysis.comparison}
- Équivalent : ${summary.bestOption.analysis.impactEquivalent}

⚠️ OPTION LA PLUS POLLUANTE : ${summary.worstOption.name}
- Émissions totales : ${summary.worstOption.totalEmissions.toFixed(2)} kg CO2e pour ${tripDistance} km
- Par km : ${summary.worstOption.emissionsPerKm.toFixed(4)} kg CO2e/km
- Note : ${summary.worstOption.analysis.rating}
- Impact : ${summary.worstOption.analysis.absoluteRating}
- ${summary.worstOption.analysis.comparison}

💡 POINT CLÉ : En choisissant ${summary.bestOption.name} au lieu de ${summary.worstOption.name}, vous économisez ${summary.totalEmissionsSaved} kg CO2e sur ce trajet de ${tripDistance} km !

📊 STATISTIQUES DU TRAJET :
- Distance : ${tripDistance} km
- Émissions moyennes par km : ${summary.averageEmissionsPerKm} kg CO2e/km
- Émissions totales moyennes : ${summary.averageTotalEmissions} kg CO2e

🚗 TOUTES LES OPTIONS DE TRANSPORT (classées par impact total) :

${transportData.map((t, i) => `
${i + 1}. ${t.name}
   - Total pour le trajet : ${t.totalEmissions.toFixed(2)} kg CO2e (pour ${tripDistance} km)
   - Par kilomètre : ${t.emissionsPerKm.toFixed(4)} kg CO2e/km
   - Catégorie : ${t.analysis.category}
   - Note : ${t.analysis.rating}
   - ${t.analysis.comparison}
   - Équivalent concret : ${t.analysis.impactEquivalent}
   - Recommandation : ${t.analysis.recommendation}
`).join('')}

---
Cette analyse proportionnelle montre l'impact environnemental RÉEL de votre trajet de ${tripDistance} km.
Le classement change selon la distance - ce qui est optimal pour les courts trajets peut ne pas l'être pour les longs !

Comment puis-je vous aider à prendre la décision de voyage la plus écologique ?
`;

// Créer également un résumé court pour des réponses rapides
const shortSummary = `
Pour un trajet de ${tripDistance} km :
🌱 Meilleur choix : ${summary.bestOption.name} (${summary.bestOption.totalEmissions.toFixed(2)} kg CO2e)
⚠️ À éviter : ${summary.worstOption.name} (${summary.worstOption.totalEmissions.toFixed(2)} kg CO2e)
💰 Économie potentielle : ${summary.totalEmissionsSaved} kg CO2e
`;

return [{
  json: {
    summary: summary,
    aiContext: contextMessage,
    shortSummary: shortSummary,
    transportData: transportData,
    tripDistance: tripDistance,
    timestamp: new Date().toISOString(),
    language: 'fr'
  }
}];
